         let ws: Workspace = {} as Workspace;

-        if (authProvisioned) {
+        if (scopeId) {
           // use the client ID to get a token against the workspace (tokenOnly), and set the workspace roles in the context
-          await apiCall(
-            `${ApiEndpoint.Workspaces}/${workspaceId}`,
-            HttpMethod.Get,
-            scopeId,
-            undefined,
-            ResultType.JSON,
